  "IP": "neorv32_hwspinlock",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Spinlock state",
      "Unit": "neorv32_hwspinlock",
      "Information": "The 32-bit state records the ownership or availability of each hardware spinlock, on which software mutual exclusion depends. A bus access can update the state and the response returns selected or all lock bits.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The lock state is mutable control state and line 45 allows a bus request to change it, so unauthorized modification can violate lock ownership. A corrupted or stuck lock value can make software wait indefinitely for a lock, while the state is updated at line 45 and returned at lines 68-70.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "A malicious bus master could issue accesses that force a lock to the wrong value, allowing conflicting users to proceed or leaving a resource permanently locked.",
      "Enters Through": [
        "bus_req_i.rw"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        45
      ],
      "Held Lines": [
        42,
        45
      ],
      "Exit Lines": [
        68,
        70
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Lock selection",
      "Unit": "neorv32_hwspinlock",
      "Information": "The one-hot selection identifies which lock an access updates or reports. It is needed to direct each lock operation, but no port carries the selection as a value because the address only decides it.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The selection is computed from the request address at line 51 and controls lock updates and returned data at lines 44 and 68, so a changed decode can target the wrong lock. Selecting a wrong or no lock can withhold the intended lock update or status, because sel gates the update at line 44 and masks returned data at line 68.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "A malicious or fault-injected address decode could steer an access to a different or no lock, corrupting synchronization and preventing the intended lock operation.",
